import{_ as r,l as s,o as e,c as n,v as l,p as i,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"黄金律与动态无效率","description":"","frontmatter":{"title":"黄金律与动态无效率","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/golden-rule.md","filePath":"econ/golden-rule.md","lastUpdated":1789023840000}'),m={name:"econ/golden-rule.md"};function c(E,a,_,g,f,u){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="黄金律与动态无效率" tabindex="-1">黄金律与动态无效率 <a class="header-anchor" href="#黄金律与动态无效率" aria-label="Permalink to &quot;黄金律与动态无效率&quot;">​</a></h1><div class="epigraph"><p>使稳态消费最大的资本密度，要求净边际产出等于人口与技术的增长率；再多的资本是养活机器，不是养活人。</p><footer>—— Phelps, The Golden Rule of Accumulation, AER 1961；对照 Ramsey 1928 的最优储蓄</footer></div><p><a href="/econ/solow-residual">上一课</a>（索洛残差）。在此之上，储蓄率 \\(s\\) 当成外生参数，并指出稳态消费不必对 \\(s\\) 单调。本课的缺口就是这条比较静态：哪个 \\(s\\)（或哪个 \\(k^*\\)）使 \\(c^*\\) 最大，以及「资本太多」在什么意义上是无效率。Ramsey 的最优增长给出修正黄金律；叠代模型里还可能真正过度积累。内生 \\(g\\) 仍留到下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛稳态 \\(c^*=(1-s)f(k^*(s))\\)。提高 \\(s\\) 一边抬 \\(k^*\\) 与产出，一边压消费份额。极大化 \\(c^*\\) 的一阶条件是</p> \\[f&#39;(k_{\\mathrm{gold}})=n+g+\\delta, \\]<p>即净边际产出等于有效摊薄。这是 Phelps 的黄金律：稳态像一个被黄金规则约束的计划者，「对自己的后代做自己希望上一代做过的事」。它还不是家庭欧拉方程——那里会出现时间偏好 \\(\\rho\\)。</p><p>若 \\(k^*\\gt k_{\\mathrm{gold}}\\)，少储蓄可以在每一期稳态都吃得更多：这是动态无效率。索洛模型里 \\(s\\) 外生，可以落在无效率区。无限寿命的 Ramsey 家庭通常不会自愿走过去，因为资本回报会低于时间偏好所要求的。叠代（Diamond）可以，因为当代人并不内部化后代。</p><p><span class="marginnote">黄金律最大化的是稳态消费，不是过渡路径的贴现效用。Ramsey 的修正黄金律是 \\(f&#39;(k)=\\rho+\\theta g+\\delta\\)（符号随效用写法而定），\\(k\\) 低于黄金律，为的是提前消费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在索洛图上，\\(c^*\\) 是 \\(f(k)\\) 与 \\((n+g+\\delta)k\\) 的垂直距离。距离最大处切线平行，即 \\(f&#39;=n+g+\\delta\\)。对应的储蓄率 \\(s_{\\mathrm{gold}}=(n+g+\\delta)k_{\\mathrm{gold}}/f(k_{\\mathrm{gold}})\\)。比较：\\(s\\gt s_{\\mathrm{gold}}\\) 则过度积累。</p><p>Ramsey–Cass–Koopmans 把 \\(s\\) 换成欧拉</p> \\[\\frac{\\dot{c}}{c}=\\frac{1}{\\theta}\\bigl(f&#39;(k)-\\delta-\\rho-\\theta g\\bigr), \\]<p>稳态回到修正黄金律。Hall 的随机欧拉是后课消费，本课只借用确定性计划者。判断动态无效率的可观察代理常是：资本净回报是否低于增长率（\\(r\\lt n\\) 一类），经验上有争议，本课只给判据。</p>',14)),(e(),i(h,null,{default:t(()=>[p(o,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOLOW%5B%22%E7%B4%A2%E6%B4%9B%E5%A4%96%E7%94%9F%20s%22%5D%20--%3E%20GOLD%5B%22%E9%BB%84%E9%87%91%E5%BE%8B%20f'%3Dn%2Bg%2B%CE%B4%22%5D%0A%20%20GOLD%20--%3E%20DYN%5B%22k%3Ek_gold%EF%BC%9A%E5%8A%A8%E6%80%81%E6%97%A0%E6%95%88%E7%8E%87%22%5D%0A%20%20RAMSEY%5B%22Ramsey%20%E6%9C%80%E4%BC%98%22%5D%20--%3E%20MOD%5B%22%E4%BF%AE%E6%AD%A3%E9%BB%84%E9%87%91%E5%BE%8B%E5%90%AB%20%CF%81%22%5D%0A%20%20MOD%20--%3E%20EFF%5B%22%E9%80%9A%E5%B8%B8%E5%8A%A8%E6%80%81%E6%9C%89%E6%95%88%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="黄金律不是政策按钮" tabindex="-1">黄金律不是政策按钮 <a class="header-anchor" href="#黄金律不是政策按钮" aria-label="Permalink to &quot;黄金律不是政策按钮&quot;">​</a></h3><p>把 \\(s\\) 降到 \\(s_{\\mathrm{gold}}\\) 在索洛里立刻提高稳态 \\(c^*\\)，但过渡期若资本已经过多，减少投资会先改变 \\(I\\) 与短期 \\(y\\)。账户上 \\(S=I\\) 仍是恒等。本课不谈如何用税收逼近黄金律，那是公共财政。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过度积累的直觉：机器的边际产出已经不够弥补把资源锁进 \\(K\\) 的机会成本（以消费计）。每一代若能协议少留一点 \\(K\\)，稳态消费全面上升——帕累托改进发生在时间之间。无限寿命主体会自己贴现，停在修正黄金律；有限寿命加遗产不完全，才可能停在黄金律另一侧。</p><p>外生 \\(g\\) 仍然决定人均消费的长期增长率。黄金律只选水平。若 \\(g\\) 本身依赖资本或知识，黄金律的切线条件要重写——那是内生增长的计划者问题，本课不预先做。</p><p>可观察代理常拿资本净回报是否低于增长率（\\(r\\lt n\\) 一类）来猜动态无效率。经验有争议，本课只给判据：索洛可以落在无效率区，因为 \\(s\\) 外生；Ramsey 通常不会。</p><p><span class="marginnote">叠代（Diamond）里当代人不必内部化后代，过度积累可以是均衡。无限寿命加利他遗产会把模型推回 Ramsey。本课不把 OLG 整章搬进来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>黄金律不管风险、人力资本与环境资本。也不回答「谁的消费」：代表性主体藏掉分配。公司资本结构与 MM 无关本课的 \\(K\\)。把 \\(s\\) 降到黄金律在过渡期会改变 \\(I\\) 与短期 \\(y\\)，账户上 \\(S=I\\) 仍是恒等——又一次禁止把恒等当政策工具。</p><p>后课默认：索洛可以动态无效率；Ramsey 通常有效但 \\(k\\) 低于黄金律。下一课打开 \\(g\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(c^*\\) 最大要求 \\(f&#39;(k)=n+g+\\delta\\)；更高的 \\(s\\) 可能动态无效率。</li><li>Ramsey 用 \\(\\rho\\) 修正黄金律，稳态增长仍靠外生 \\(g\\)。</li><li>叠代可以过度积累；无限寿命通常不会。</li><li>黄金律是稳态消费，不是过渡路径的贴现效用最大。</li><li>\\(g\\) 从哪来，是内生增长的缺口。</li><li>出处：Phelps, AER 1961；Ramsey, Economic Journal 1928。</li></ul>',12))])}const A=r(m,[["render",c]]);export{k as __pageData,A as default};
